/* Live lists (no demo data): workers from /api/status, chats from SubwayChat, files from the project, skills, hub apps.
   Each loads on init and refreshes on its HUD stream event (push.js re-emits /api/events as "subway:event"); nothing polls. */
const WORKERS=[];
let QUOTAS=[];
function loadWorkers(){fetch("/api/status",{cache:"no-store"}).then(r=>r.ok?r.json():null).then(d=>{if(!d)return;QUOTAS=(d.quotas&&d.quotas.providers)||[];
  const live=w=>["running","pending_approval","stopping","queued"].includes(String(w.status||""))?0:1,seen=new Set();
  const all=[...(d.workers||[]),...(Array.isArray(d.history)?d.history:[])].filter(w=>w&&w.id&&!seen.has(w.id)&&seen.add(w.id));
  all.sort((a,b)=>live(a)-live(b)||String(b.created_at||b.started_at||"").localeCompare(String(a.created_at||a.started_at||"")));
  WORKERS.splice(0,WORKERS.length,...all.slice(0,20).map(w=>({id:w.id,role:w.role||w.id,sub:[w.provider,w.model].filter(Boolean).join(" · ")||String(w.status||"")})));
  if(typeof renderAll==="function")renderAll();}).catch(()=>{});}
let liveChats=null;
const mapChats=d=>(Array.isArray(d)?d:(d&&d.chats)||[]).slice(0,40).map(c=>({id:c.id,title:c.title||c.label||String(c.id).slice(0,8),sub:c.source||"",open:!!c.open,project:c.project_dir||c.project||"",at:c.mtime||c.updated_at||0}));
function setChats(d){liveChats=mapChats(d);if(typeof renderAll==="function")renderAll();}
function chatList(){return liveChats||[];}
function threadId(){return st.thread||(st.chat&&st.chat.id)||"";}
let coverage={},covAt=0,thState={},thAt=0,thFor="";
