function postAction(path,body,okMsg){return fetch(path,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)}).then(async r=>{const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(r.status===404?"endpoint not available":(d.error||d.message||`HTTP ${r.status}`));return d;}).then(d=>{window.toast?.(okMsg);return d;},e=>{window.toast?.(`${okMsg.split(" →")[0]} failed: ${e.message}`);throw e;});}
let FILES=[],filesQ=null,filesT=0;
function wantFiles(q){if(q===filesQ)return;filesQ=q;clearTimeout(filesT);filesT=setTimeout(()=>{
  fetch(`/api/composer/project_files?q=${encodeURIComponent(q)}&limit=30`,{cache:"no-store"}).then(r=>r.ok?r.json():null).then(d=>{if(!d||filesQ!==q)return;
    FILES=(d.files||[]).map(f=>({path:f.path,lines:f.lines,locked:f.locked?(f.locked_by||"another chat"):""}));if(typeof renderMenu==="function")renderMenu();}).catch(()=>{});},150);}

