const st={station:"here",stationPicked:false,peers:[],command:null,target:null,steer:"stack",mode:"auto",clock:{kind:"now"},prov:"claude",model:"sonnet",effort:"medium",effortNote:"",
  files:[],skills:[],needs:[],apps:[],principal:null,handoff:true,responding:false,queue:[],menuIdx:0,menuDismissed:false};
