/* Port of local_models.resolve_effort: keep the level if offered, else the nearest by ladder index (ties go up). */
function startEffort(m){const l=m.efforts||[];return !l.length?null:l.includes("medium")?"medium":l[l.length-1];}
function carryEffort(to,e){const l=to.efforts;st.effortNote="";if(!l||!l.length)return null;if(!e)return startEffort(to);if(l.includes(e))return e;
  const r=rank(e);const pick=[...l].sort((a,b)=>Math.abs(rank(a)-r)-Math.abs(rank(b)-r)||rank(b)-rank(a))[0];
  st.effortNote=`${elabel(e)} → ${elabel(pick)} (${to.name} offers ${l.map(x=>elabel(x)).join(", ")})`;return pick;}

/* ---------- popovers (open upward) ---------- */
let openPop=null;
function pop(trigger,build,{align="start",wide=false}={}){
  const panel=h("div",{class:`cmp-pmenu ${align==="end"?"right":""} ${wide?"wide":""}`,role:"menu",hidden:true});
  const wrap=h("span",{class:"cmp-pop"},trigger,panel);
  trigger.setAttribute("aria-haspopup","menu");trigger.setAttribute("aria-expanded","false");
  function close(focus){if(panel.hidden)return;panel.hidden=true;trigger.setAttribute("aria-expanded","false");if(openPop===api)openPop=null;if(focus)trigger.focus();}
  function open(){if(openPop&&openPop!==api)openPop.close();panel.replaceChildren(...build(close).filter(Boolean));panel.hidden=false;
    const rect=trigger.getBoundingClientRect(),vh=window.innerHeight||document.documentElement.clientHeight||600;
    const above=Math.max(80,Math.floor(rect.top-12)),below=Math.max(80,Math.floor(vh-rect.bottom-12));
    if(above>=below){panel.style.top="auto";panel.style.bottom="calc(100% + 8px)";panel.style.maxHeight=`${Math.min(380,above)}px`;}
    else{panel.style.bottom="auto";panel.style.top="calc(100% + 6px)";panel.style.maxHeight=`${Math.min(380,below)}px`;}
    panel.style.overflowY="auto";
    trigger.setAttribute("aria-expanded","true");openPop=api;
    if(panel.classList.contains("sched")){panel.querySelector("input[type=radio]:checked,input[type=radio]")?.focus();return;}
    const items=[...panel.querySelectorAll("[data-item]")];(items.find(b=>b.getAttribute("aria-checked")==="true")||panel.querySelector("input")||items[0])?.focus();}
  trigger.addEventListener("click",()=>panel.hidden?open():close());
  panel.addEventListener("keydown",e=>{if(panel.classList.contains("sched")){if(e.key==="Escape"){e.preventDefault();e.stopPropagation();close(true);}return;}
    const items=[...panel.querySelectorAll("[data-item]")].filter(b=>b.offsetParent);const i=items.indexOf(document.activeElement);
    if(e.key==="ArrowDown"||e.key==="ArrowUp"){e.preventDefault();if(items.length)items[(i+(e.key==="ArrowDown"?1:-1)+items.length)%items.length].focus();}
    else if(e.key==="Escape"){e.preventDefault();e.stopPropagation();close(true);}
    else if(e.key==="Tab"){close();}});
  const api={el:wrap,close,open,rebuild(){if(!panel.hidden)open();}};return api;}
