/* ---------- menus ---------- */
function buildApps(close){
  if(!APPS.length) return[label("Apps"),label("No apps available")];
  const items=[label("Apps")];
  for(const a of APPS){
    const status=a.status||"";
    const name=a.name||a.id;
    const attached=st.apps.some(x=>x.id===a.id);
    if(status==="unsupported"){
      items.push(item({title:name,hint:a.reason||"Unsupported",close,onSelect:()=>{showResult(a.reason||"Unsupported");}}));
      continue;
    }
    if(status==="not_connected"){
      items.push(item({title:name,hint:"Not connected · click to connect (macOS will ask for permission)",checked:false,close,onSelect:()=>{
        showResult("Waiting for macOS permission…");
        window.SubwayChat.connectApp(a.id).then(r=>{
          if(r&&r.ok){showResult(`${name} connected`);}else{showResult((r&&r.error)||`${name} failed to connect`);}
          loadApps(true);
        }).catch(e=>{showResult((e&&e.message)||`${name} failed to connect`);loadApps(true);});
      }}));
      continue;
    }
    const toggle=()=>{
      const idx=st.apps.findIndex(x=>x.id===a.id);
      if(idx>=0)st.apps.splice(idx,1);
      else st.apps.push({id:a.id,name:a.name||a.id,station:a.station||st.station});
      renderAll();
    };
    items.push(item({title:name,hint:attached?"Remove from brief":"Attach to brief",checked:attached,close,onSelect:toggle}));
    if(status==="connected"&&(a.id==="reminders"||a.id==="calendar"||(window.SubwayChat&&window.SubwayChat.disconnectApp))){
      items.push(item({title:`Disconnect ${name}`,hint:"Disconnect from Subway",close,onSelect:()=>{const idx=st.apps.findIndex(x=>x.id===a.id);if(idx>=0){st.apps.splice(idx,1);renderAll();}window.SubwayChat.disconnectApp(a.id).then(()=>{loadApps(true);}).catch(()=>loadApps(true));}}));
    }
  }
  return items;
}
