/* ---------- suggestions: / commands, @ targets, # files ---------- */
const caretText=()=>ta.value.slice(0,ta.selectionStart??ta.value.length);
const slashQ=()=>!st.command&&ta.value.startsWith("/")&&!/\s/.test(ta.value)?ta.value.slice(1).toLowerCase():null;
const atQ=()=>{const m=caretText().match(/(?:^|\s)@([\w.-]*)$/);return m?m[1].toLowerCase():null;};
const dollarQ=()=>{const m=caretText().match(/(?:^|\s)\$([\w.:-]*)$/);return m?m[1].toLowerCase():null;};
const plusQ=()=>{const m=caretText().match(/(?:^|\s)\+([\w.:-]*)$/);return m?m[1].toLowerCase():null;};
const MCPS=[];
function loadMcps(){fetch("/api/mcp/hub/servers",{cache:"no-store"}).then(r=>r.ok?r.json():null).then(d=>{if(!d)return;MCPS.splice(0,MCPS.length,...(d.servers||[]).filter(x=>x&&x.key&&x.supported!==false));}).catch(()=>{});}
const hashQ=()=>{const m=caretText().match(/(?:^|\s)#([\w./-]*)$/);return m?m[1].toLowerCase():null;};
function suggestions(){const sq=slashQ();if(sq!==null)return COMMANDS.filter(c=>c.label.toLowerCase().includes(sq)).map(c=>({kind:"command",c,label:c.label,sub:c.d,i:c.i}));
  const dq=dollarQ();if(dq!==null)return SKILLS.filter(k=>k.name.toLowerCase().includes(dq)&&!st.skills.includes(k.name)).slice(0,20).map(k=>({kind:"skill",label:k.name,sub:k.description||"Skill",i:"magic-wand"}));
  const pq=plusQ();if(pq!==null)return MCPS.filter(x=>`${x.key} ${x.name||""}`.toLowerCase().includes(pq)&&!st.needs.includes(x.key)).slice(0,20).map(x=>({kind:"mcp",id:x.key,label:x.name||x.key,sub:[x.transport,(x.owners||[]).join(", ")].filter(Boolean).join(" · ")||"MCP server",i:"plug"}));
  const hq=hashQ();if(hq!==null)wantFiles(hq);if(hq!==null)return FILES.filter(f=>f.path.includes(hq)).map(f=>({kind:"file",label:f.path,sub:`${f.lines} lines${f.locked?` · locked by ${f.locked}`:""}`,i:f.locked?"lock-simple":"file",f}));
  const aq=atQ();if(aq===null)return[];
  return[...WORKERS.filter(w=>`${w.id} ${w.role}`.toLowerCase().includes(aq)).map(w=>({kind:"worker",id:w.id,label:w.role,sub:`${w.id} · ${w.sub}`,i:"robot"})),
    ...chatList().filter(c=>`${c.id} ${c.title}`.toLowerCase().includes(aq)).map(c=>({kind:"chat",id:c.id,label:c.title,sub:`${c.id} · ${c.sub}`,i:"chat-circle"}))];}
