  if(!open){ta.removeAttribute("aria-activedescendant");return;}st.menuIdx=Math.min(st.menuIdx,sugs.length-1);
  const group=sugs[0].kind==="command"?"Commands":sugs[0].kind==="file"?"Code packets":"Targets";
  listbox.replaceChildren(label(group),...sugs.map((s,i)=>h("div",{class:"cmp-opt",role:"option",id:`cmpSug${i}`,"aria-selected":String(i===st.menuIdx),
    on:{pointerenter:()=>{st.menuIdx=i;renderMenu();},pointerdown:e=>{e.preventDefault();pickSug(s);}}},
    ico(s.i),h("span",{class:"cmp-item-txt"},h("span",{class:"cmp-item-title"},s.kind==="command"?h("span",{class:"cmp-slash"},"/"):null,s.label),h("span",{class:"cmp-item-hint"},s.sub)),
    s.kind==="worker"?h("span",{class:"cmp-tag"},"steer"):s.kind==="chat"?h("span",{class:"cmp-tag"},"mail"):null)));
