function submit(now){if(!canSend())return;const t=st.target,c=st.command,p=prov(),m=model(),n=lines(),lane=laneOf(),worker=t&&t.kind==="worker";
  const text=ta.value.trim()||(c?`/${c.id}`:`${st.files.length} attachment${st.files.length>1?"s":""}`);
  const clear=()=>{ta.value="";st.files=[];st.skills=[];st.needs=[];st.apps=[];st.command=null;autosize();};
  if(c&&(c.id==="principal"||c.id==="initiator")){const arg=(ta.value.trim().replace(/^\/(principal|initiator)\s*/,"")||(c.id==="principal"&&st.principal?st.principal.id:"")).trim();const th=threadId();
    if(!arg||!th){window.toast?.(!th?"Pick a chat first":`Usage: /${c.id} <chat>`);return;}
    const body=c.id==="principal"?{thread:th,principal_id:arg}:{thread:th,initiator_id:arg};
    if(c.id==="principal"){st.principal={id:arg,pending:true};renderAll();}
    postAction(`/api/composer/${c.id}`,body,`${c.id==="principal"?"Principal":"Initiator"} → ${arg}`).then(()=>{if(c.id==="principal"){st.principal={id:arg};thAt=0;renderAll();}},()=>{});clear();return;}
  /* Scheduled, or the chat is mid-turn: it waits on the server instead (⌘↵ sends now). */
  if(!worker&&!c&&st.mode!=="dry"&&!(st.chat&&st.chat.fresh)){const ql=st.chat?st.chat.id:lane;
    if(st.clock.kind!=="now"){enqueue(text,ql,st.clock);st.clock={kind:"now"};clear();renderAll();return;}
    if(ql!=="here"&&busy(ql)&&!now){enqueue(text,ql);clear();renderAll();return;}}
  if(!worker&&st.penHeldElsewhere&&!now){st.queue.push({id:"pen-"+Date.now(),text,lane,when:{kind:"next"},penQueued:true});clear();renderAll();return;}
  if(st.chat&&!c&&st.mode!=="dry"){
    if(st.chat.fresh){
      const atts=st.files.map(f=>f.path).filter(Boolean);
      let t2=text; if(atts.length) t2+="\n\nAttached files:\n"+atts.map(p=>`- ${p}`).join("\n");
      const label=st.chat.srcLabel||st.chat.source||"chat";
      st.responding=true;live.textContent="Starting new "+label+" chat.";renderAll();
      fetch("/api/chat/new",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({provider:st.prov,model:st.model||"",effort:st.effort||"",text:t2,project_dir:(st.chat&&st.chat.project_dir)||"",no_folder:!(st.chat&&st.chat.project_dir)})})
        .then(async r=>{const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||d.message||`HTTP ${r.status}`);return d;})
        .then(d=>{const chatId=d.chat_id||d.session_id||d.sid||"";
          showResult(`Started new ${label} chat.`);live.textContent="New "+label+" chat.";
          document.dispatchEvent(new CustomEvent("composer:sent",{detail:{chat:chatId,chat_id:chatId,method:"new",provider:st.prov||"",model:st.model||""}}));
          if(chatId) window.SubwayComposer?.setChat({id:chatId,source:st.prov,srcLabel:label,label:"New chat"});})
        .catch(e=>{showResult("Couldn't start chat: "+e.message);live.textContent="Send failed.";
          document.dispatchEvent(new CustomEvent("composer:send-failed",{detail:{chat:st.chat&&st.chat.id,error:e.message}}));})
        .finally(()=>{st.responding=false;renderAll();});
      clear();return;}
    const onNow=st.chat.current||st.chat.source;if(st.prov&&onNow&&st.prov!==onNow){swapChat(text,clear);return;}
    sendToChat(text,clear);return;}
  if(!worker&&!t&&!c&&st.mode==="dry"){dryRun(text,p,m);return;}
  if(!worker&&!t&&!c&&st.mode==="mail"){enqueue(text,"here",st.clock.kind==="now"?{kind:"next"}:st.clock);st.clock={kind:"now"};clear();renderAll();return;}
  if(!worker&&!t&&!c){const tasks=splitTasks(text);if(tasks.length>1)spawnConcurrent(tasks,p,m);else spawnReal(text,p,m);clear();return;}
  if(worker&&st.mode!=="dry"){instructWorker(t,text);clear();return;}
  if(t&&t.kind==="chat"&&!c&&st.mode!=="dry"){const atts=st.files.map(f=>f.path).filter(Boolean);clear();
    SCq.send(t.id,{text,source:t.source||laneSrc[t.id]||"",model:st.model||"",effort:st.effort||"",attachments:atts}).then(r=>{const msg=r.ok?`Sent to ${laneLabel(t.id)}.`:`Not sent: ${r.error}`;showResult(msg);live.textContent=msg;});return;}
  if(c&&st.mode!=="dry"){runCommand(c,text);clear();renderAll();return;}
  const msg=c?`Dry run: /${c.id} would run. Nothing sent.`:`Plan: ${n} worker${n>1?"s":""} on ${p.label} · ${m.name}. Nothing sent.`;
  clear();showResult(msg);live.textContent=msg;renderAll();}
/* Slash commands: each calls its real route and shows the server's answer (no simulated results). */
function cmdResult(label,r){const ok=r&&r.ok!==false&&!r.error;const msg=ok?`${label}: ${r.result||r.message||"done"}`:`${label} failed: ${(r&&(r.error||r.message))||"unknown error"}`;
  showResult(String(msg).split("\n").filter(Boolean).slice(0,6).join("\n"));live.textContent=ok?`${label} done.`:`${label} failed.`;}
function cmdPost(path,body){return fetch(path,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)})
  .then(async r=>{const d=await r.json().catch(()=>({}));return r.ok?{ok:true,...(typeof d==="object"&&d?d:{result:String(d)})}:{ok:false,error:d.error||d.message||`HTTP ${r.status}`};})
  .catch(e=>({ok:false,error:String(e&&e.message||e)}));}
function runCommand(c,text){const arg=String(text||"").replace(new RegExp(`^/${c.id}\\s*`),"").trim();
  const chat=(st.target&&st.target.kind==="chat")?{id:st.target.id,source:st.target.source||laneSrc[st.target.id]||""}:(st.chat?{id:st.chat.id,source:st.chat.source||""}:null);
  const needChat=()=>{if(!chat){showResult(`Pick a chat with @ (or open one) for /${c.id}.`);return false;}return true;};
  const turnId=()=>{const x=SCq.get(chat.id)||{},ts=(x.turns||(x.d&&x.d.turns)||[]);for(let i=ts.length-1;i>=0;i--){const t=ts[i]||{};const id=t.tid||t.id||t.uuid;if(id)return String(id);}return"";};
  switch(c.id){
    case"iterate":{if(!arg){showResult("Usage: /iterate <task>");return;}const pt={provider:st.prov||"auto",model:st.model||"",effort:st.effort||""};
      cmdPost("/api/iteration/start",{task:arg,participants:[pt,{...pt}],track:"main"}).then(r=>cmdResult("Iteration",r));return;}
    case"broadcast":{if(!arg){showResult("Usage: /broadcast <decision>");return;}cmdPost("/api/broadcast",{message:arg,track:"main"}).then(r=>cmdResult("Broadcast",r));return;}
    case"mail":{if(!needChat())return;if(!arg){showResult("Usage: /mail <note>");return;}
      SCq.queue.add(chat.id,{text:arg,source:chat.source}).then(r=>cmdResult(`Mail to ${laneLabel(chat.id)}`,r&&r.ok?{ok:true,result:"queued for delivery"}:r));return;}
    case"claim":{const [fp,...rest]=arg.split(/\s+/);if(!fp){showResult("Usage: /claim <path> <why>");return;}
      cmdPost("/api/claim",{filepath:fp,purpose:rest.join(" ")||"Composer claim",duration:300}).then(r=>cmdResult(`Claim ${fp}`,r));return;}
    case"rewind":{if(!needChat())return;const tid=arg||turnId();if(!tid){showResult("No checkpoint found in this chat yet.");return;}
      SCq.fork(chat.id,tid,"","").then(r=>{const d=(r&&r.data)||{};cmdResult("Rewind",r&&r.ok?{ok:true,result:`forked at ${tid}${d.id||d.chat_id?` → ${d.id||d.chat_id}`:""}`}:r);});return;}
    case"compact":{if(!needChat())return;SCq.compact(chat.id).then(r=>cmdResult("Compact",r&&r.ok?{ok:true,result:"thread folded into highlights"}:r));return;}
    case"export":{const th=threadId();if(!th){showResult("Open a chat to export its thread.");return;}const fmt=["md","json","patch"].includes(arg)?arg:"md";
      fetch(`/api/composer/thread_export?thread=${encodeURIComponent(th)}&format=${fmt}`,{cache:"no-store"}).then(async r=>{if(!r.ok){const d=await r.json().catch(()=>({}));throw new Error(d.error||`HTTP ${r.status}`);}return r.blob();})
        .then(b=>{const a=h("a",{href:URL.createObjectURL(b),download:`thread-${String(th).slice(0,8)}.${fmt}`});document.body.append(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove();},0);cmdResult("Export",{ok:true,result:`${fmt} downloaded`});})
        .catch(e=>cmdResult("Export",{ok:false,error:e.message}));return;}
    default:showResult(`/${c.id} has no handler.`);}}
function stop(){st.responding=false;showResult("Stopped waiting here. Anything already sent keeps running; stop a worker from its card.");
  live.textContent="Stopped.";renderAll();ta.focus();}

/* ---------- input ---------- */
ta.addEventListener("input",()=>{st.menuDismissed=false;st.menuIdx=0;autosize();renderAll();pillIn.value=ta.value;});
ta.addEventListener("click",()=>renderMenu());
ta.addEventListener("keydown",e=>{if(e.isComposing)return;
  if(!cmdMenu.hidden&&sugs.length){
    if(e.key==="ArrowDown"||e.key==="ArrowUp"){e.preventDefault();st.menuIdx=(st.menuIdx+(e.key==="ArrowDown"?1:-1)+sugs.length)%sugs.length;renderMenu();return;}
    if(e.key==="Enter"||e.key==="Tab"){e.preventDefault();pickSug(sugs[st.menuIdx]);return;}
    if(e.key==="Escape"){e.preventDefault();st.menuDismissed=true;renderMenu();return;}}
  if(e.key==="Enter"&&(e.metaKey||e.ctrlKey)&&st.target&&st.target.kind==="worker"){e.preventDefault();st.steer="recall";submit();return;}
  if(e.key==="Enter"&&!e.shiftKey){e.preventDefault();submit(e.metaKey||e.ctrlKey);}
  else if(e.key==="Escape"){e.preventDefault();st.responding?stop():close();}
  else if(e.key==="Backspace"&&!ta.value&&ta.selectionStart===0){if(st.command){e.preventDefault();st.command=null;renderAll();}else if(st.target){e.preventDefault();setTarget(null);}}});
